def number_to_words(n: int) -> str:
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 0 or n > 999999:
        raise ValueError("n must be between 0 and 999999")

    ones = [
        "zero", "one", "two", "three", "four", "five", "six", "seven",
        "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety",
    ]

    def under_thousand(x: int) -> str:
        parts = []
        if x >= 100:
            parts.append(ones[x // 100] + " hundred")
            x %= 100
        if x >= 20:
            word = tens[x // 10]
            if x % 10:
                word += "-" + ones[x % 10]
            parts.append(word)
        elif x > 0:
            parts.append(ones[x])
        return " ".join(parts)

    if n == 0:
        return "zero"

    result = []
    if n >= 1000:
        result.append(under_thousand(n // 1000) + " thousand")
        n %= 1000
    if n:
        result.append(under_thousand(n))
    return " ".join(result)
